        y[row] = y_value;
        local_dot += v[row] * y_value;
      }
    }
    const float block_dot = block_sum_leader(local_dot, local_reduction);
    if (tid == 0) {
      scalars[2 + cta] = block_dot;
    }
    cluster.sync();

    float dot = 0.0f;
    #pragma unroll
    for (int block = 0; block < kBlocksPerMatrix; ++block) {
      dot += scalars[2 + block];
    }
    const float correction = dot * (-0.5f * tau);
    const int update_lane = tid & 31;
    const int cluster_warp = cluster_tid >> 5;
    const int cluster_warps = cluster_threads >> 5;
    for (int update_row = cluster_warp; update_row < size;
         update_row += cluster_warps) {
      const int row_start = local_rows[base + update_row] + base;
      const float row_y = y[update_row] + correction * v[update_row];
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        const float column_y = y[update_col] + correction * v[update_col];
        matrix[batch_offset + row_start + update_col] -=
            v[update_row] * column_y + row_y * v[update_col];
      }
    }
    for (int index = cluster_tid; index < size; index += cluster_threads) {
      const float stored =
          index == 0 ? off_diagonal[vector_offset + column] : v[index];
      matrix[batch_offset + local_rows[base + index] + column] = stored;
      column_reflectors[packed_n352_reflector_index(
          matrix_count, matrix_index, base + index, column)] =
          index == 0 ? 1.0f : v[index];
    }
    cluster.sync();
  }

  if (cta != 0) {
    return;
  }
  for (int column = kClusterColumns; column < n - 2; ++column) {
      const int base = column + 1;
      const int size = n - base;
      float local_norm = 0.0f;
      for (int index = tid + 1; index < size; index += blockDim.x) {
        const float value = matrix[
            batch_offset + local_rows[base + index] + column];
        local_norm += value * value;
      }
      const float norm_sum = block_sum_leader(local_norm, local_reduction);
      if (tid == 0) {
        const float alpha =
            matrix[batch_offset + local_rows[base] + column];
        const float tail_norm = sqrtf(norm_sum);
        float beta = alpha;
        float tau = 0.0f;
        float inverse = 0.0f;
        if (tail_norm != 0.0f) {
          beta = -copysignf(hypotf(alpha, tail_norm), alpha);
          tau = (beta - alpha) / beta;
          inverse = 1.0f / (alpha - beta);
        }
        diagonal[vector_offset + column] =
            matrix[batch_offset + local_rows[column] + column];
        off_diagonal[vector_offset + column] = beta;
        taus[vector_offset + column] = tau;
        local_reduction[0] = tau;
        local_reduction[1] = inverse;
      }
      __syncthreads();

      const float tau = local_reduction[0];
      const float inverse = local_reduction[1];
      for (int index = tid; index < size; index += blockDim.x) {
        local_v[index] = index == 0
            ? 1.0f
            : matrix[batch_offset + local_rows[base + index] + column] *
                inverse;
      }
      __syncthreads();

      constexpr int kDotWidth = 8;
      const int dot_group = tid / kDotWidth;
      const int dot_lane = tid & (kDotWidth - 1);
      float local_dot = 0.0f;
      for (int row = dot_group; row < size;
           row += static_cast<int>(blockDim.x) / kDotWidth) {
        float sum = 0.0f;
        const int row_start = local_rows[base + row] + base;
        for (int inner = dot_lane; inner <= row; inner += kDotWidth) {
          sum += matrix[batch_offset + row_start + inner] * local_v[inner];
        }
        const int upper_offset =
            (dot_lane - ((row + 1) & (kDotWidth - 1)) + kDotWidth) &
            (kDotWidth - 1);
        for (int inner = row + 1 + upper_offset; inner < size;
             inner += kDotWidth) {
          sum += matrix[batch_offset +
                        local_rows[base + inner] + base + row] *
              local_v[inner];
        }
        const unsigned int mask = __activemask();
        #pragma unroll
        for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
          sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
        }
        if (dot_lane == 0) {
          const float y_value = tau * sum;
          local_y[row] = y_value;
          local_dot += local_v[row] * y_value;
        }
      }
      const float dot = block_sum_leader(local_dot, local_reduction);
      if (tid == 0) {
        local_reduction[0] = dot * (-0.5f * tau);
      }
      __syncthreads();

      const float correction = local_reduction[0];
      const int update_lane = tid & 31;
      const int update_warp = tid >> 5;
      const int update_warps = static_cast<int>(blockDim.x) >> 5;
      for (int update_row = update_warp; update_row < size;
           update_row += update_warps) {
        const int row_start = local_rows[base + update_row] + base;
        const float row_y =
            local_y[update_row] + correction * local_v[update_row];
        for (int update_col = update_lane; update_col <= update_row;
             update_col += 32) {
          const float column_y =
              local_y[update_col] + correction * local_v[update_col];
          matrix[batch_offset + row_start + update_col] -=
              local_v[update_row] * column_y + row_y * local_v[update_col];
        }
      }
      for (int index = tid; index < size; index += blockDim.x) {
        const float stored = index == 0
            ? off_diagonal[vector_offset + column]
            : local_v[index];
        matrix[batch_offset + local_rows[base + index] + column] = stored;
        column_reflectors[packed_n352_reflector_index(
            matrix_count, matrix_index, base + index, column)] =
            index == 0 ? 1.0f : local_v[index];
      }
      __syncthreads();
    }

  if (tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + local_rows[n - 2] + n - 2];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + local_rows[n - 1] + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + local_rows[n - 1] + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

