template <int kBlocksPerMatrix, int kN>
__global__ void reduce_n352_panel_clustered(
    const float* __restrict__ matrix,
    float* __restrict__ panel_v,
    float* __restrict__ panel_w,
    float* __restrict__ diagonal,
    float* __restrict__ off_diagonal,
    float* __restrict__ taus,
    int panel_start, int panel_width) {
  constexpr int n = kN;
  constexpr int kPartialNorm = 0;
  constexpr int kTau = kBlocksPerMatrix;
  constexpr int kInverse = kTau + 1;
  constexpr int kPartialDot = kInverse + 1;
  constexpr int kCorrection = kPartialDot + kBlocksPerMatrix;
  constexpr int kProjectedW = 16;
  constexpr int kProjectedV = kProjectedW + 128;
  constexpr int kMaxPanelWidth = 16;
  extern __shared__ float local_shared[];
  float* local_v = local_shared;
  float* local_panel_v = local_v + n;
  float* local_panel_w = local_panel_v + kMaxPanelWidth * n;
  float* local_reduction = local_panel_w + kMaxPanelWidth * n;
  float* local_scalars = local_reduction + 32;

  cg::cluster_group cluster = cg::this_cluster();
  const int tid = static_cast<int>(threadIdx.x);
  const int cta = static_cast<int>(cluster.block_rank());
