  const int matrix_count = static_cast<int>(gridDim.x) / kBlocksPerMatrix;
  const int cluster_tid = cta * static_cast<int>(blockDim.x) + tid;
  const int cluster_threads =
      kBlocksPerMatrix * static_cast<int>(blockDim.x);
  const int64_t matrix_offset =
      static_cast<int64_t>(matrix_index) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(matrix_index) * n;
  float* v = cluster.map_shared_rank(local_v, 0);
  float* shared_panel_v = cluster.map_shared_rank(local_panel_v, 0);
  float* shared_panel_w = cluster.map_shared_rank(local_panel_w, 0);
  float* scalars = cluster.map_shared_rank(local_scalars, 0);

  for (int index = cluster_tid; index < 2 * panel_width * n;
       index += cluster_threads) {
    shared_panel_v[index] = 0.0f;
  }
  cluster.sync();

  for (int panel_column = 0; panel_column < panel_width; ++panel_column) {
    const int column = panel_start + panel_column;
    const int base = column + 1;
    const int size = n - base;

    float local_norm = 0.0f;
