        const int row_offset = row - panel_start - 1;
        const float row_v = shared_panel_v[previous * n + row_offset];
        const float row_w = shared_panel_w[previous * n + row_offset];
        const float column_v =
            shared_panel_v[previous * n + panel_column - 1];
        const float column_w =
            shared_panel_w[previous * n + panel_column - 1];
        value -= row_v * column_w + row_w * column_v;
      }
      v[index] = value;
      if (index != 0) {
        local_norm += value * value;
      }
    }
    const float norm_sum = block_sum_leader(local_norm, local_reduction);
    if (tid == 0) {
      scalars[kPartialNorm + cta] = norm_sum;
    }
    cluster.sync();

    if (cluster_tid == 0) {
      float total_norm = 0.0f;
      #pragma unroll
      for (int block = 0; block < kBlocksPerMatrix; ++block) {
        total_norm += scalars[kPartialNorm + block];
      }
      float current_diagonal =
          matrix[matrix_offset + column * n + column];
      if (panel_column != 0) {
        for (int previous = 0; previous < panel_column; ++previous) {
          const float column_v =
              shared_panel_v[previous * n + panel_column - 1];
          const float column_w =
              shared_panel_w[previous * n + panel_column - 1];
          current_diagonal -= 2.0f * column_v * column_w;
        }
      }
      const float alpha = v[0];
      const float tail_norm = sqrtf(total_norm);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
