      #pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        projected_w += __shfl_down_sync(
            0xffffffffu, projected_w, offset);
        projected_v += __shfl_down_sync(
            0xffffffffu, projected_v, offset);
