         row_index += cluster_threads / kDotWidth) {
      const int row = base + row_index;
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        sum += matrix[matrix_offset + row * n + base + inner] * v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        for (int previous = 0; previous < panel_column; ++previous) {
          const int row_offset = panel_column + row_index;
          const float row_v =
              shared_panel_v[previous * n + row_offset];
          const float row_w =
              shared_panel_w[previous * n + row_offset];
          sum -= row_v * scalars[kProjectedW + previous] +
              row_w * scalars[kProjectedV + previous];
        }
        const float y = scalars[kTau] * sum;
        shared_panel_w[panel_column * n + panel_column + row_index] = y;
        panel_w[packed_n352_reflector_index(
            matrix_count, matrix_index, row, column)] = y;
        local_dot += v[row_index] * y;
      }
    }
    const float dot_sum = block_sum_leader(local_dot, local_reduction);
    if (tid == 0) {
      scalars[kPartialDot + cta] = dot_sum;
    }
    cluster.sync();

    if (cluster_tid == 0) {
      float total_dot = 0.0f;
      #pragma unroll
      for (int block = 0; block < kBlocksPerMatrix; ++block) {
        total_dot += scalars[kPartialDot + block];
      }
      scalars[kCorrection] = -0.5f * scalars[kTau] * total_dot;
    }
    cluster.sync();

    const float correction = scalars[kCorrection];
    for (int index = cluster_tid; index < size;
         index += cluster_threads) {
      const int row = base + index;
      const int64_t output_index = packed_n352_reflector_index(
          matrix_count, matrix_index, row, column);
      const int shared_index = panel_column * n + panel_column + index;
      const float w = shared_panel_w[shared_index] + correction * v[index];
      shared_panel_w[shared_index] = w;
      panel_w[output_index] = w;
    }
    cluster.sync();
  }
}

__global__ void finalize_n352_tridiagonal(
    const float* __restrict__ matrix, float* __restrict__ diagonal,
    float* __restrict__ off_diagonal, float* __restrict__ taus) {
  constexpr int n = 352;
  const int matrix_index = static_cast<int>(blockIdx.x);
  const int64_t matrix_offset = static_cast<int64_t>(matrix_index) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(matrix_index) * n;
  if (threadIdx.x == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[matrix_offset + (n - 2) * n + n - 2];
    diagonal[vector_offset + n - 1] =
        matrix[matrix_offset + (n - 1) * n + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[matrix_offset + (n - 1) * n + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

