for (int panel_column = 0; panel_column < panel_width; ++panel_column) {
  const int column = panel_start + panel_column;
  const int base = column + 1;
  const int size = n - base;

  if (cta == 0) {
    float local_norm = 0.0f;
    for (int index = tid; index < size; index += blockDim.x) {
      const int row = base + index;
      float value = matrix[matrix_offset + row * n + column];
      for (int previous = 0; previous < panel_column; ++previous) {
        const int row_offset = row - panel_start - 1;
        const float row_v = shared_panel_v[previous * n + row_offset];
        const float row_w = shared_panel_w[previous * n + row_offset];
        const float column_v =
            shared_panel_v[previous * n + panel_column - 1];
        const float column_w =
            shared_panel_w[previous * n + panel_column - 1];
        value -= row_v * column_w + row_w * column_v;
      }
      v[index] = value;
      if (index != 0) {
        local_norm += value * value;
      }
    }
    const float norm_sum = block_sum_leader(local_norm, local_reduction);
    if (tid == 0) {
    float current_diagonal =
        matrix[matrix_offset + column * n + column];
    if (panel_column != 0) {
      for (int previous = 0; previous < panel_column; ++previous) {
        const float column_v =
            shared_panel_v[previous * n + panel_column - 1];
        const float column_w =
            shared_panel_w[previous * n + panel_column - 1];
        current_diagonal -= 2.0f * column_v * column_w;
      }
    }
    const float alpha = v[0];
    const float tail_norm = sqrtf(norm_sum);
    float beta = alpha;
    float tau = 0.0f;
    float inverse = 0.0f;
    if (tail_norm != 0.0f) {
      beta = -copysignf(hypotf(alpha, tail_norm), alpha);
      tau = (beta - alpha) / beta;
      inverse = 1.0f / (alpha - beta);
    }
    diagonal[vector_offset + column] = current_diagonal;
    off_diagonal[vector_offset + column] = beta;
    taus[vector_offset + column] = tau;
    scalars[kTau] = tau;
    scalars[kInverse] = inverse;
    }
  }
  cluster.sync();

  const float inverse = scalars[kInverse];
  for (int index = cluster_tid; index < size;
       index += cluster_threads) {
    const int row = base + index;
    const float reflector = index == 0 ? 1.0f : v[index] * inverse;
    v[index] = reflector;
    shared_panel_v[panel_column * n + panel_column + index] = reflector;
    panel_v[packed_n352_reflector_index(
        matrix_count, matrix_index, row, column)] = reflector;
  }
  cluster.sync();

  const int lane = cluster_tid & 31;
  const int cluster_warp = cluster_tid >> 5;
  const int cluster_warps = cluster_threads >> 5;
  for (int previous = cluster_warp; previous < panel_column;
       previous += cluster_warps) {
    float projected_w = 0.0f;
    float projected_v = 0.0f;
    for (int index = lane; index < size; index += 32) {
      const float reflector = v[index];
      const int row_offset = panel_column + index;
      projected_w += shared_panel_w[
          previous * n + row_offset] * reflector;
      projected_v += shared_panel_v[
          previous * n + row_offset] * reflector;
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      projected_w += __shfl_down_sync(
          0xffffffffu, projected_w, offset);
      projected_v += __shfl_down_sync(
          0xffffffffu, projected_v, offset);
    }

