template <int kBlocksPerMatrix, int kN>
__global__ void reduce_n352_panel_clustered(
    const float* __restrict__ matrix,
    float* __restrict__ panel_v,
    float* __restrict__ panel_w,
    float* __restrict__ diagonal,
    float* __restrict__ off_diagonal,
    float* __restrict__ taus,
    int panel_start, int panel_width) {
